def lr(e, de, q=' '):
    return NUCID + '  L ' + str(e).ljust(10) + str(de).ljust(2) + ' '*58 + q

def gr(eg, ri, dri='', q=' '):
    return NUCID + '  G ' + str(eg).ljust(10) + '  ' + ' ' + str(ri).ljust(7) + str(dri).ljust(2) + ' '*48 + q

