g_lookup = {}
for ei_raw, de_raw, ql, gammas in RAW:
    ei = Decimal(str(ei_raw))
    q_gamma = '?' if ei in TENTATIVE else ' '
    rows = [(ei - Decimal(str(ef)), ri, dri) for ef, ri, dri in gammas]
    rows.sort()
    g_lookup[str(ei)] = [gr(str(eg), ri, dri, q_gamma) for eg, ri, dri in rows]

filepath = r'd:\X\ND\ENSDF\A34\Cl34\raw\1977DA02.ens'
with open(filepath, 'r', encoding='ascii') as f:
    lines = f.read().splitlines()

body_lines = lines[2:]

old_lines = []
new_lines = []
for line in body_lines:
    lp = line.ljust(80)[:80]
    old_lines.append(lp)
    new_lines.append(lp)
    e_field = lp[9:19].rstrip()
    if e_field in g_lookup:
        new_lines.extend(g_lookup[e_field])

old_body = '\n'.join(old_lines)
new_body = '\n'.join(new_lines)

outdir = r'd:\X\ND\ENSDF\.github\temp'
